  const axisLine = BABYLON.MeshBuilder.CreateLines(`originAxis${i}`, { points: [originAxisBase, dir] }, scene) as BABYLON.LinesMesh;
  axisLine.color = color;
  axisLine.parent = volumeRoot;
});

